class DmDict(dict):
    def __getitem__(self, dm):
        if dm in self:
            return super().__getitem__(dm)
        dm1 = sorted([dm2 for dm2 in self if str(dm2).startswith(str(dm))])
        if dm1:
            return super().__getitem__(dm1[0])
        return None

def partial_keys(dm):
    return DmDict(dm)


